import { afterEach, expect, it } from "D:/projexts/moe-next/node_modules/vitest/dist/index.js";
import { GOAL_ID, PROJECT_ID, closeStores } from "D:/projexts/moe-next/apps/daemon/src/bootstrap/bootstrap-test-fixtures.ts";
import { approveGate1, boundWorld, committedRevision } from "D:/projexts/moe-next/apps/daemon/src/planning/plan-reject-test-fixtures.ts";
import { designRevisionFixture } from "D:/projexts/moe-next/apps/daemon/src/design/design-test-fixtures.ts";
import { readDesignRevision, submitDesignRevision } from "D:/projexts/moe-next/apps/daemon/src/design/design-store.ts";
import { handleDesignReadRequest } from "D:/projexts/moe-next/apps/daemon/src/http/design-read.ts";
import { CAPABILITIES } from "D:/projexts/moe-next/apps/daemon/src/daemon-command-vocabulary.ts";
import { WIRE_PROTOCOL_VERSION } from "D:/projexts/moe-next/apps/daemon/src/http/http-contract.ts";
import { mapDesignAnswer } from "D:/projexts/moe-next/apps/control-room/src/live/live-design.ts";
afterEach(closeStores);
it("decodes an Order from the real committed design through the real HTTP handler", () => {
  const store = boundWorld();
  const contractRef = committedRevision(store);
  approveGate1(store, contractRef);
  const revision = { ...designRevisionFixture(), dataModel: [{ entity: "Order", fields: ["id"], relations: [] }] };
  expect(submitDesignRevision(store, { commandId: "cmd-design-browser", contractRef,
    correlationId: "corr-design-browser", decidedAt: "2026-09-05T09:00:00.000Z", expectedVersion: 0,
    goalRef: GOAL_ID, principalId: "designer", projectId: PROJECT_ID, revision }).ok).toBe(true);
  const answer = handleDesignReadRequest({
    authenticator: { authenticate: () => ({ verdict: "AUTHENTICATED", principal: {
      principalId: "operator", projectId: PROJECT_ID, capabilities: [CAPABILITIES.GOAL] } }) },
    designReads: { read: (input) => readDesignRevision(store, input) },
  }, { body: new TextEncoder().encode(JSON.stringify({ goalRef: GOAL_ID })), credential: "fixture",
    protocolVersion: WIRE_PROTOCOL_VERSION });
  expect(answer.kind).toBe("REPLY");
  if (answer.kind !== "REPLY") throw new Error("No HTTP answer");
  expect(answer.httpStatus).toBe(200);
  const wire = JSON.parse(JSON.stringify(answer.body));
  expect(mapDesignAnswer(answer.httpStatus, wire)).toMatchObject({ status: "DESIGN",
    record: { version: 1, goalRef: GOAL_ID, revision: { dataModel: [{ entity: "Order", fields: ["id"], relations: [] }] } } });
  expect(mapDesignAnswer(200, { ...wire, extra: true })).toEqual({ status: "ERROR",
    code: "DESIGN_RESPONSE_INVALID", layer: "CONTROL_ROOM_LIVE_DESIGN" });
  console.log("REAL_HTTP_DESIGN Order version=1; extra-key ERROR DESIGN_RESPONSE_INVALID @ CONTROL_ROOM_LIVE_DESIGN");
});
